"""Pure-Python markdown section extractor — line-based scan, no external lib."""

from __future__ import annotations


def extract_section(markdown: str, heading: str, max_chars: int = 1200) -> str:
    """Return the body of the first `## <heading>` section (or `### ...`).

    Returns an empty string if the section is missing. Truncated to `max_chars`
    on a sentence boundary where possible. Heading match is case-insensitive
    and ignores surrounding whitespace.
    """
    lines = markdown.splitlines()
    capturing = False
    captured: list[str] = []
    target = heading.strip().lower()
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("## ") or stripped.startswith("### "):
            if capturing:
                # Hit the next section heading; stop capturing
                break
            # Match the H2/H3 line text against target
            text = stripped.lstrip("#").strip().lower()
            if text == target or text.startswith(target + " ") or text.startswith(target + ":"):
                capturing = True
                continue
        if capturing:
            captured.append(line)

    body = "\n".join(captured).strip()
    if len(body) <= max_chars:
        return body
    # Truncate on the last sentence boundary within max_chars
    truncated = body[:max_chars]
    for sep in (". ", "! ", "? ", "\n\n"):
        idx = truncated.rfind(sep)
        if idx > max_chars * 0.6:
            return truncated[: idx + 1].rstrip() + " …"
    return truncated.rstrip() + " …"
